const crypto = require('crypto');

// Rejects anything that Convex did not sign with the shared secret in the
// last five minutes. The signature covers the raw request body.
const secret = $env.AUTOMATION_SECRET;
if (!secret) throw new Error('AUTOMATION_SECRET is not set for n8n');

const headers = $input.first().json.headers;
const timestamp = String(headers['x-lendloop-timestamp'] ?? '');
const received = String(headers['x-lendloop-signature'] ?? '').replace(/^sha256=/, '');
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');

const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
const fresh = /^\d+$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
const matches =
  received.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));

if (!fresh || !matches) return [{ json: { valid: false } }];
return [{ json: { valid: true, event: JSON.parse(raw) } }];

// Turns a loan event into one plain-text message for its recipient.
const { event } = $input.first().json;
const period = `${event.startDate} to ${event.endDate}`;
const messages = {
  'loan.requested': {
    subject: `${event.otherFirstName} wants to borrow your ${event.toolName}`,
    text: `${event.otherFirstName} asked to borrow your ${event.toolName} from ${period}. Open LendLoop to approve or decline.`,
  },
  'loan.approved': {
    subject: `Your request for the ${event.toolName} was approved`,
    text: `${event.otherFirstName} approved your request. The ${event.toolName} is yours from ${period}.`,
  },
  'loan.declined': {
    subject: `Your request for the ${event.toolName} was declined`,
    text: `Your request for the ${event.toolName} (${period}) was declined. Other tools are on the board.`,
  },
  'loan.cancelled': {
    subject: `The loan of the ${event.toolName} was cancelled`,
    text: `The loan of the ${event.toolName} planned for ${period} was cancelled.`,
  },
  'loan.returned': {
    subject: `Thanks for returning the ${event.toolName}`,
    text: `${event.otherFirstName} confirmed that the ${event.toolName} is back. Thanks for returning it.`,
  },
};
const message = messages[event.kind];
if (!message) throw new Error(`Unknown event kind: ${event.kind}`);

return [{
  json: {
    eventId: event.eventId,
    loanId: event.loanId,
    mail: {
      From: { Email: 'no-reply@lendloop.test', Name: 'LendLoop' },
      To: [{ Email: event.recipient.email, Name: event.recipient.firstName }],
      Subject: message.subject,
      Text: `Hi ${event.recipient.firstName},\n\n${message.text}\n\nLendLoop`,
    },
  },
}];

const crypto = require('crypto');

// Signs `${timestamp}.${payload}` the same way convex/lib/signature.ts does.
function signedHeaders(payload) {
  const secret = $env.AUTOMATION_SECRET;
  if (!secret) throw new Error('AUTOMATION_SECRET is not set for n8n');
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const digest = crypto.createHmac('sha256', secret).update(`${timestamp}.${payload}`).digest('hex');
  return { 'X-LendLoop-Timestamp': timestamp, 'X-LendLoop-Signature': `sha256=${digest}` };
}

// The mail node continues on error, so its output says whether it worked.
const result = $input.first().json;
const source = $('Compose message').first().json;
const failed = result.error !== undefined;
const body = JSON.stringify({
  loanId: source.loanId,
  kind: 'notification',
  key: `notification:${source.eventId}`,
  status: failed ? 'failed' : 'sent',
  detail: failed ? String(result.error.message ?? result.error).slice(0, 200) : undefined,
});
return [{ json: { body, headers: signedHeaders(body), failed } }];
